

# This file was *autogenerated* from the file exp3_bruteforce.sage
from sage.all_cmdline import *   # import sage library

_sage_const_32 = Integer(32); _sage_const_40 = Integer(40); _sage_const_48 = Integer(48); _sage_const_56 = Integer(56); _sage_const_64 = Integer(64); _sage_const_72 = Integer(72); _sage_const_80 = Integer(80); _sage_const_3 = Integer(3); _sage_const_10 = Integer(10); _sage_const_777 = Integer(777); _sage_const_0p02 = RealNumber('0.02'); _sage_const_1000 = Integer(1000); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2)# =============================================================================
# Experiment 3 -- Wiener's attack vs. brute force over d < n^(1/4)/3
#   Brute force needs about n^(1/4)/3 = 2^(bits/4) candidates (exponential in
#   the key size); Wiener needs O(log n) convergents (polynomial).
#   Only SMALL moduli are used because brute force explodes quickly.
# Output: results/exp3_bruteforce.csv
# Run:    sage exp3_bruteforce.sage [--quick]
# =============================================================================
import sys
load("wiener_lib.sage")

QUICK  = "--quick" in sys.argv
SIZES  = [_sage_const_32 , _sage_const_40 , _sage_const_48 , _sage_const_56 , _sage_const_64 ] if QUICK else [_sage_const_32 , _sage_const_40 , _sage_const_48 , _sage_const_56 , _sage_const_64 , _sage_const_72 , _sage_const_80 ]
TRIALS = _sage_const_3  if QUICK else _sage_const_10 
SEED   = _sage_const_777 
set_random_seed(SEED)

rows = []
print(f"{'bits':>5} {'wiener conv.':>13} {'wiener ms':>10} {'brute cand.':>12} {'brute ms':>10}")
for bits in SIZES:
    acc = []
    for _ in range(TRIALS):
        n, e, d, p, q = generate_weak_key(bits)
        bound = d_upper_bound(n)            # attacker only knows this bound

        # Wiener
        res = wiener_attack(e, n)
        assert is_correct_recovery(res, d, p, q), "Wiener failed on a weak key!"
        w_time = time_call(wiener_attack, e, n, min_time=_sage_const_0p02 )

        # Brute force (candidates tried == recovered d, since we count up from 1)
        d_bf = brute_force_d(e, n, bound)
        assert d_bf is not None
        bf_time = time_call(brute_force_d, e, n, bound, min_time=_sage_const_0p02 )

        rows.append(dict(bits=bits, n_bits=n.nbits(), d=d,
                         wiener_convergents=res[_sage_const_3 ], wiener_time_s=w_time,
                         bf_candidates=d_bf, bf_time_s=bf_time))
        acc.append((res[_sage_const_3 ], w_time * _sage_const_1000 , d_bf, bf_time * _sage_const_1000 ))
    avg = [sum(col) / len(acc) for col in zip(*acc)]
    print(f"{bits:>5} {float(avg[_sage_const_0 ]):>13.1f} {float(avg[_sage_const_1 ]):>10.4f} "
          f"{float(avg[_sage_const_2 ]):>12.0f} {float(avg[_sage_const_3 ]):>10.3f}", flush=True)

write_csv("results/exp3_bruteforce.csv",
          ["bits", "n_bits", "d", "wiener_convergents", "wiener_time_s",
           "bf_candidates", "bf_time_s"], rows)

